style.css:
@-moz-document domain("roblox.com") {
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-image: url("https://64.media.tumblr.com/75c65f3601c070c6c3448793726d2f8d/16fc488ecbdcb3d3-a5/s1280x1920/0b6af7bdbed761dd9c7fd0b38f39325c303c65e6.gif");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    z-index: -1;
    opacity: 0.6;
    pointer-events: none;
  }

  .container-main, .content, .navbar, .footer-container {
    background-color: rgba(255, 255, 255, 0.9) !important;
  }
}
